+  margin:0;
+  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
+  color:var(--gs-text);
+  background:var(--gs-bg);
+  line-height:1.6;
+}
+img{max-width:100%;height:auto;display:block}
+a{color:inherit;text-decoration:none}
+
+/* Typography */
+.h1,.h2,.h3,.h4{
+  font-family: "Playfair Display", Georgia, "Times New Roman", serif;
+  letter-spacing:-0.02em;
+  margin:0;
+}
+.h1{font-size:clamp(2.0rem, 2.5vw + 1rem, 3.1rem);line-height:1.1}
+.h2{font-size:clamp(1.5rem, 1.2vw + 1rem, 2.2rem);line-height:1.15}
+.h3{font-size:1.35rem;line-height:1.2}
+.h4{font-size:1.1rem;line-height:1.25}
+
+.eyebrow{
+  font-size:0.82rem;
+  letter-spacing:0.13em;
+  text-transform:uppercase;
+  color:rgba(255,255,255,0.78);
+}
+.muted{color:var(--gs-subtle)}
+.lead{font-size:1.07rem;color:rgba(255,255,255,0.85)}
+
+/* Layout */
+.container{max-width:var(--container);margin:0 auto;padding:0 20px}
+.section{padding:72px 0}
+.section-tight{padding:52px 0}
+.grid{display:grid;gap:18px}
+.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}
+.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}
+.grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}
+@media (max-width: 980px){
+  .grid-4{grid-template-columns:repeat(2,minmax(0,1fr))}
+  .grid-3{grid-template-columns:repeat(2,minmax(0,1fr))}
+  .grid-2{grid-template-columns:1fr}
+}
+@media (max-width: 560px){
+  .grid-3,.grid-4{grid-template-columns:1fr}
+}
+
+/* Buttons */
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  height:44px;
+  padding:0 16px;
+  border-radius:999px;
+  border:1px solid transparent;
+  font-weight:600;
+  font-size:0.95rem;
+  transition: transform 180ms ease, box-shadow 180ms ease, background-color 180ms ease, color 180ms ease, border-color 180ms ease;
+  cursor:pointer;
+}
+.btn:focus-visible{outline:3px solid rgba(161, 98, 7, 0.35); outline-offset:3px}
+.btn-primary{background:var(--gs-accent);color:#fff;box-shadow:0 10px 24px rgba(161,98,7,0.24)}
+.btn-primary:hover{transform:translateY(-1px);box-shadow:0 16px 30px rgba(161,98,7,0.28)}
+.btn-secondary{background:rgba(255,255,255,0.10);color:#fff;border-color:rgba(255,255,255,0.18)}
+.btn-secondary:hover{background:rgba(255,255,255,0.14);transform:translateY(-1px)}
+.btn-ghost{background:transparent;border-color:var(--gs-border);color:var(--gs-text)}
+.btn-ghost:hover{background:rgba(10,22,40,0.04)}
+
+/* Cards */
+.card{
+  background:var(--gs-surface);
+  border:1px solid var(--gs-border);
+  border-radius:var(--radius-md);
+  box-shadow: var(--shadow-sm);
+}
+.card-pad{padding:22px}
+.card:hover{box-shadow: var(--shadow-md)}
+.card .meta{font-size:0.82rem;color:var(--gs-subtle);display:flex;gap:10px;align-items:center;flex-wrap:wrap}
+.tag{display:inline-flex;align-items:center;height:24px;padding:0 10px;border-radius:999px;background:rgba(10,22,40,0.06);color:var(--gs-text-2);font-size:0.78rem;font-weight:600}
+.link{display:inline-flex;gap:10px;align-items:center;font-weight:650;color:var(--gs-navy)}
+.link:hover{text-decoration:underline}
+
+/* Header / Nav */
+.site-header{
+  position:sticky;
+  top:0;
+  z-index:1000;
+  background:rgba(10,22,40,0.78);
