+}
+.header-inner{display:flex;align-items:center;justify-content:space-between;gap:18px;height:74px}
+.brand{display:flex;align-items:center;gap:12px;color:#fff;min-width:180px}
+.brand-mark{width:34px;height:34px;border-radius:12px;background:linear-gradient(135deg,#183356, #0A1628);border:1px solid rgba(255,255,255,0.12);box-shadow:0 10px 20px rgba(0,0,0,0.18)}
+.brand-name{font-weight:800;letter-spacing:0.02em}
+.brand-sub{display:block;font-size:0.78rem;color:rgba(255,255,255,0.72);margin-top:2px}
+
+.nav{display:flex;align-items:center;gap:18px}
+.nav a, .nav button{
+  color:rgba(255,255,255,0.88);
+  font-weight:600;
+  padding:10px 10px;
+  border-radius:999px;
+}
+.nav a:hover, .nav button:hover{background:rgba(255,255,255,0.08);color:#fff}
+.nav button{background:transparent;border:0;font:inherit;cursor:pointer}
+.nav .is-active{background:rgba(255,255,255,0.10);color:#fff}
+
+.nav-cta{display:flex;align-items:center;gap:10px}
+
+.mobile-toggle{display:none}
+
+/* Mega menu */
+.mega{
+  position:absolute;
+  left:0;right:0;
+  top:74px;
+  padding:16px 0 24px;
+  background:rgba(10,22,40,0.84);
+  backdrop-filter: blur(18px);
+  border-bottom:1px solid rgba(255,255,255,0.10);
+  transform-origin: top;
+  opacity:0;
+  pointer-events:none;
+  transform: translateY(-8px) scale(0.985);
+  transition: opacity 180ms ease, transform 220ms ease;
+}
+.mega[data-open="true"]{opacity:1;pointer-events:auto;transform: translateY(0) scale(1)}
+.mega-panel{display:grid;grid-template-columns:1.2fr 0.9fr 0.9fr;gap:18px}
+.mega-card{
+  border-radius:var(--radius-lg);
+  border:1px solid rgba(255,255,255,0.14);
+  background:linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.06));
+  padding:18px;
+}
+.mega-title{color:#fff;font-weight:800;letter-spacing:0.01em;margin-bottom:8px}
+.mega-sub{color:rgba(255,255,255,0.74);font-size:0.92rem;margin:0 0 12px}
+.mega-group{display:flex;flex-direction:column;gap:10px}
+.mega-link{
+  display:flex;align-items:center;justify-content:space-between;
+  gap:14px;
+  padding:10px 12px;
+  border-radius:14px;
+  color:rgba(255,255,255,0.92);
+  border:1px solid rgba(255,255,255,0.10);
+  background:rgba(10,22,40,0.20);
+  transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease;
+}
+.mega-link:hover{background:rgba(255,255,255,0.10);border-color:rgba(255,255,255,0.18);transform:translateY(-1px)}
+.mega-col h4{margin:0 0 10px;color:rgba(255,255,255,0.9);font-size:0.95rem;letter-spacing:0.12em;text-transform:uppercase}
+.mega-col a{display:block;padding:9px 10px;border-radius:12px;color:rgba(255,255,255,0.86)}
+.mega-col a:hover{background:rgba(255,255,255,0.08);color:#fff}
