+/* Mobile nav drawer */
+.mobile-drawer{
+  position:fixed;inset:0;
+  background:rgba(8,12,18,0.62);
+  opacity:0;pointer-events:none;
+  transition:opacity 200ms ease;
+  z-index:1200;
+}
+.mobile-drawer[data-open="true"]{opacity:1;pointer-events:auto}
+.mobile-panel{
+  position:absolute;right:0;top:0;bottom:0;
+  width:min(420px, 92vw);
+  background:rgba(10,22,40,0.92);
+  backdrop-filter: blur(18px);
+  border-left:1px solid rgba(255,255,255,0.10);
+  transform:translateX(8px);
+  transition:transform 220ms ease;
+  padding:16px;
+}
+.mobile-drawer[data-open="true"] .mobile-panel{transform:translateX(0)}
+.mobile-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 4px 14px}
+.mobile-close{background:transparent;border:1px solid rgba(255,255,255,0.14);color:#fff;border-radius:999px;height:40px;padding:0 14px;font-weight:650;cursor:pointer}
