+.mobile-nav{display:flex;flex-direction:column;gap:10px}
+.mobile-item{border:1px solid rgba(255,255,255,0.12);border-radius:16px;overflow:hidden;background:rgba(255,255,255,0.05)}
+.mobile-link{display:flex;align-items:center;justify-content:space-between;gap:12px;color:#fff;padding:14px 14px;font-weight:650}
+.mobile-link:hover{background:rgba(255,255,255,0.06)}
+.mobile-sub{padding:8px 10px 12px;display:none}
+.mobile-sub a{display:block;color:rgba(255,255,255,0.86);padding:10px 10px;border-radius:12px}
+.mobile-sub a:hover{background:rgba(255,255,255,0.08);color:#fff}
+.mobile-item[data-open="true"] .mobile-sub{display:block}
+.mobile-cta{display:flex;gap:10px;margin-top:14px}
+
+@media (max-width: 980px){
+  .nav,.nav-cta{display:none}
+  .mobile-toggle{display:inline-flex}
+  .mega{display:none}
+}
