+  padding:86px 0 74px;
+  color:#fff;
+  background: radial-gradient(900px 420px at 25% 10%, rgba(161,98,7,0.22), transparent 55%),
+              linear-gradient(180deg, rgba(10,22,40,0.94), rgba(10,22,40,0.90));
+  overflow:hidden;
+}
+.hero:before{
+  content:"";
+  position:absolute;inset:-1px;
+  background-image:
+    linear-gradient(180deg, rgba(10,22,40,0.30), rgba(10,22,40,0.85)),
+    url('assets/hero-skyline.jpg');
+  background-size:cover;
+  background-position:center;
+  filter:saturate(1.05) contrast(1.03);
+  z-index:0;
+}
+.hero-inner{position:relative;z-index:1;display:grid;grid-template-columns:1.2fr 0.8fr;gap:26px;align-items:end}
+.hero-card{
+  border-radius:var(--radius-lg);
+  border:1px solid rgba(255,255,255,0.16);
+  background:linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0.06));
+  box-shadow: 0 30px 80px rgba(0,0,0,0.28);
+  padding:22px;
+}
+.hero-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
+.metric{border-radius:16px;border:1px solid rgba(255,255,255,0.14);background:rgba(10,22,40,0.28);padding:14px}
+.metric b{display:block;font-size:1.15rem}
+.metric span{display:block;color:rgba(255,255,255,0.78);font-size:0.82rem}
+@media (max-width: 980px){
+  .hero-inner{grid-template-columns:1fr}
+  .hero{padding:74px 0 62px}
+}
+
+/* Announcement banner */
+.announce{background:linear-gradient(90deg, rgba(161,98,7,0.14), rgba(14,165,168,0.10));border:1px solid rgba(10,22,40,0.10);border-left:0;border-right:0}
