+  grid-template-columns:0.9fr 1.1fr;
+  gap:18px;
+  align-items:stretch;
+}
+.tablist{display:flex;flex-direction:column;gap:10px}
+.tabbtn{
+  width:100%;
+  text-align:left;
+  border-radius:18px;
+  padding:14px 14px;
+  background:var(--gs-surface);
+  border:1px solid var(--gs-border);
+  cursor:pointer;
+  transition:transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
+}
+.tabbtn:hover{transform:translateY(-1px);box-shadow:var(--shadow-sm)}
+.tabbtn[aria-selected="true"]{border-color:rgba(161,98,7,0.42);box-shadow:0 18px 45px rgba(161,98,7,0.14)}
+.tabbtn .kicker{display:block;color:var(--gs-subtle);font-size:0.82rem;letter-spacing:0.13em;text-transform:uppercase}
+.tabbtn .label{display:block;font-weight:850;font-size:1.06rem;margin-top:4px}
+.tabpanel{border-radius:var(--radius-lg);background:linear-gradient(180deg, rgba(10,22,40,0.03), rgba(10,22,40,0.02));border:1px solid var(--gs-border);padding:24px}
+.panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap}
+.panel-head p{margin:10px 0 0;color:var(--gs-text-2)}
+.fade{animation:fadeIn 220ms ease}
+@keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
+@media (prefers-reduced-motion: reduce){
+  .fade{animation:none}
+  .btn,.tabbtn,.mega,.mobile-drawer,.mobile-panel{transition:none}
+}
+@media (max-width: 980px){.tabs{grid-template-columns:1fr}}
+
+/* Footer */
+.footer{background:var(--gs-navy);color:rgba(255,255,255,0.86)}
+.footer a{color:rgba(255,255,255,0.86)}
+.footer a:hover{color:#fff;text-decoration:underline}
+.footer-top{padding:54px 0 26px;border-bottom:1px solid rgba(255,255,255,0.10)}
+.footer-bottom{padding:18px 0 30px;display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}
+.footer h4{margin:0 0 12px;color:#fff;font-family:Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial;letter-spacing:0.12em;text-transform:uppercase;font-size:0.86rem}
+.footer ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
+
+/* Utility */
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}
+.divider{height:1px;background:var(--gs-border)}
+
+/* Page hero (inner pages) */
+.page-hero{position:relative;padding:72px 0 54px;color:#fff;background:linear-gradient(180deg, rgba(10,22,40,0.92), rgba(10,22,40,0.88));overflow:hidden}
+.page-hero:before{content:"";position:absolute;inset:-1px;background-image:linear-gradient(180deg, rgba(10,22,40,0.45), rgba(10,22,40,0.92)), url('assets/hero-interior.jpg');background-size:cover;background-position:center;z-index:0}
+.page-hero .container{position:relative;z-index:1}
+.crumbs{display:flex;gap:10px;flex-wrap:wrap;color:rgba(255,255,255,0.75);font-size:0.92rem}
+.crumbs a:hover{text-decoration:underline}
+
+/* Capability lists */
+.cap-grid .card{transition:transform 180ms ease, box-shadow 180ms ease}
+.cap-grid .card:hover{transform:translateY(-2px)}
+.cap-grid .card h3{margin-bottom:10px}
+.cap-grid .card p{margin:0;color:var(--gs-text-2)}
+
+/* Carousel */
+.carousel{position:relative}
+.carousel-track{display:flex;gap:14px;overflow:hidden;scroll-behavior:smooth}
+.carousel-slide{min-width:calc(100% - 0px)}
+.carousel-controls{display:flex;gap:10px;justify-content:flex-end;margin-top:12px}
+.iconbtn{height:40px;min-width:40px;border-radius:999px;border:1px solid var(--gs-border);background:var(--gs-surface);cursor:pointer}
+.iconbtn:hover{background:rgba(10,22,40,0.03)}
+.iconbtn:focus-visible{outline:3px solid rgba(161, 98, 7, 0.35); outline-offset:3px}
+
+/* Forms */
+.field{display:flex;flex-direction:column;gap:8px}
+.field label{font-weight:650;color:var(--gs-text)}
+.input{
+  height:44px;
+  padding:0 14px;
+  border-radius:14px;
+  border:1px solid var(--gs-border);
+  background:var(--gs-surface);
+  font:inherit;
+}
+.input:focus{outline:none;border-color:rgba(161,98,7,0.55);box-shadow:0 0 0 4px rgba(161,98,7,0.12)}
+
*** End Patch
PATCH

